import {products,yen,totals,pruneOrders,filterProducts,TTL} from './core.mjs';
const $=s=>document.querySelector(s), main=$('#main'),modal=$('#modal');
const KEY='noma-demo-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={'チャコール':'#454b47','サンド':'#c9bca5','ホワイト':'#f5f3ec','オリーブ':'#838d70','ナチュラル':'#bf9a70','ブラウン':'#80624e','シルバー':'#bac1c2'};
let cart=[],orders=[],coupon='',storageOK=true;
function save(){try{localStorage.setItem(KEY,JSON.stringify({cart,orders,coupon}));}catch{storageOK=false;}}
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');cart=(Array.isArray(raw.cart)?raw.cart:[]).filter(x=>x&&products.some(p=>p.id===x.id&&p.stock>0&&p.colors.includes(x.color))&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=9).map(x=>({id:x.id,color:x.color,quantity:x.quantity}));orders=pruneOrders(raw.orders);coupon=raw.coupon==='DEMO10'?'DEMO10':'';}catch{storageOK=false;cart=[];orders=[];}save();}
load();
const cartItems=()=>cart.map(x=>({...products.find(p=>p.id===x.id),...x}));
const count=()=>cart.reduce((s,x)=>s+x.quantity,0);
function updateCount(){$('#cart-count').textContent=count();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function img(p,cls=''){return `<img class="${cls}" src="assets/${p.image}.svg" alt="${esc(p.name)}" width="400" height="400" loading="lazy">`;}
function rating(p){return `<div class="rating" aria-label="デモ評価 ${p.rating}、レビュー${p.reviews}件">★ ${p.rating.toFixed(1)} <span>(${p.reviews}) · デモ評価</span></div>`;}
function card(p){return `<article class="product"><a class="visual" href="#/product/${p.id}" aria-label="${esc(p.name)}の商品詳細">${img(p)}${p.rank<2?'<span class="badge">BEST SELLER</span>':p.stock===0?'<span class="badge">SOLD OUT</span>':''}</a><p class="category">${p.category}</p><h3><a href="#/product/${p.id}">${p.name}</a></h3>${rating(p)}<p class="price">${yen(p.price)}<small>税込</small></p><div class="swatches" aria-label="カラー ${p.colors.join('、')}">${p.colors.map(c=>`<span class="swatch" style="background:${colors[c]}"></span>`).join('')}</div></article>`;}
const empty=(title,text,link='#/',label='商品を探す')=>`<div class="empty"><h2>${title}</h2><p>${text}</p><a class="btn" href="${link}">${label}</a></div>`;
function listing(params){const query=params.get('q')||'',category=params.get('category')||'',max=Number(params.get('max'))||Infinity,stock=params.get('stock')==='1',sort=params.get('sort')||'recommended';const list=filterProducts({query,category,max,stock,sort});$('#search').value=query;const simple=!query&&!category&&!params.has('max')&&!stock&&!params.has('sort');main.innerHTML=`<div class="wrap">${simple?`<section class="hero"><div class="hero-copy"><p class="eyebrow">THE EVERYDAY EDIT / 2026</p><h1>暮らしの、<br>ちょうどいい。</h1><p>手になじむ道具。心地いい時間。<br>毎日を少し整える、私たちの定番。</p><a class="text-link" href="#/?category=インテリア">暮らしを整えるアイテムを見る →</a></div><img src="assets/hero.svg" alt="木製デスクに並ぶライト、マグ、ヘッドホン" width="750" height="400"></section>`:''}<section id="catalog" class="catalog-anchor"><div class="section-head"><h1>${query?`「${esc(query)}」の検索結果`:category?esc(category):'毎日の、定番。'}</h1><p>${simple?'暮らしに寄り添う、18のアイテム。':''}</p><button class="mobile-filter" id="mobile-filter" aria-expanded="false" aria-controls="filters">絞り込み</button></div><div class="catalog-layout"><aside class="filters" id="filters" aria-label="商品を絞り込む"><div class="filter-block"><h3>カテゴリー</h3>${['','テック','インテリア','キッチン','ファッション'].map(c=>`<label><input type="radio" name="category" value="${c}" ${category===c?'checked':''}>${c||'すべての商品'}</label>`).join('')}</div><div class="filter-block"><h3><label for="max-price">価格（税込）</label></h3><select id="max-price"><option value="">すべての価格</option value="3000" ${max===3000?'selected':''}>3,000円以下</option><option value="5000" ${max===5000?'selected':''}>5,000円以下</option><option value="10000" ${max===10000?'selected':''}>10,000円以下</option></select></div><div class="filter-block"><label><input type="checkbox" id="in-stock" ${stock?'checked':''}>在庫ありのみ</label></div><button class="reset-filters" id="clear-filters">条件をリセット</button></aside><div><div class="result-toolbar"><span><b>${list.length}</b> 件の商品</span><label>並び替え <select id="sort" aria-label="商品の並び替え">${[['recommended','おすすめ順'],['price-asc','価格の安い順'],['price-desc','価格の高い順'],['rating','評価の高い順']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="grid">${list.length?list.map(card).join(''):empty('商品が見つかりませんでした','キーワードや絞り込み条件を変えてお試しください。','#/','条件をリセット')}</div></div></div></section></div>`;
function change(k,v){if(v)params.set(k,v);else params.delete(k);navigate('#/?'+params.toString());}
$('#mobile-filter').onclick=e=>{const open=$('#filters').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);};
document.querySelectorAll('[name="category"]').forEach(e=>e.onchange=()=>change('category',e.value));$('#max-price').onchange=e=>change('max',e.target.value);$('#in-stock').onchange=e=>change('stock',e.target.checked?'1':'');$('#sort').onchange=e=>change('sort',e.target.value);$('#clear-filters').onclick=()=>navigate('#/');}
function detail(id){const p=products.find(x=>x.id===id);if(!p){main.innerHTML=`<div class="wrap">${empty('商品が見つかりません','商品一覧からお探しください。')}</div>`;return;}let color=p.colors[0],quantity=1;main.innerHTML=`<div class="wrap"><div class="breadcrumb"><a href="#/">ホーム</a> / <a href="#/?category=${p.category}">${p.category}</a> / ${p.name}</div><div class="detail"><div class="detail-visual">${img(p)}</div><div class="detail-info"><p class="eyebrow">NOMA ORIGINAL / ${p.category}</p><h1>${p.name}</h1>${rating(p)}<p class="price">${yen(p.price)}<small>税込</small></p><p class="description">${p.description}</p><div class="options"><label>カラー：<span id="chosen-color">${color}</span></label><div class="option-group">${p.colors.map((c,i)=>`<button class="option" data-color="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><label>数量</label><div class="qty"><button id="qty-minus" aria-label="数量を減らす" disabled>−</button><output id="detail-qty" aria-live="polite">1</output><button id="qty-plus" aria-label="数量を増やす">＋</button></div></div><p class="stock-text">${p.stock?'在庫あり · 1種類につき最大9点':'現在在庫切れです'}</p><button class="btn full" id="add-cart" ${!p.stock?'disabled':''}>カートに入れる</button><button class="btn secondary full" id="buy-now" ${!p.stock?'disabled':''}>今すぐ購入手続きへ</button><p class="note">税込5,000円以上でデモ送料無料。通常送料は500円。<br>この商品は架空です。実際の購入・決済・発送は行われません。</p><div class="detail-spec"><p><span>ブランド</span><span>NOMA（架空ブランド）</span></p><p><span>商品番号</span><span>NMA-${p.id.toUpperCase()}</span></p><p><span>写真・カラー</span><span>イメージイラスト / 代表色</span></p></div></div></div></div>`;
document.querySelectorAll('[data-color]').forEach(e=>e.onclick=()=>{color=e.dataset.color;$('#chosen-color').textContent=color;document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',b===e));});
function qty(d){quantity=Math.min(9,Math.max(1,quantity+d));$('#detail-qty').textContent=quantity;$('#qty-minus').disabled=quantity===1;$('#qty-plus').disabled=quantity===9;}
$('#qty-minus').onclick=()=>qty(-1);$('#qty-plus').onclick=()=>qty(1);
function add(){const line=cart.find(x=>x.id===id&&x.color===color);if(line){line.quantity=Math.min(9,line.quantity+quantity);}else cart.push({id,color,quantity});save();updateCount();}
$('#add-cart').onclick=()=>{add();toast('カートに追加しました');};$('#buy-now').onclick=()=>{add();navigate('#/checkout');};}
function summary(checkout=false){const t=totals(cartItems(),coupon);return `<aside class="summary"><h2>ご注文内容</h2><div class="sum-row"><span>商品小計（${count()}点）</span><span>${yen(t.subtotal)}</span></div>${t.discount?`<div class="sum-row"><span>DEMO10 · 10%OFF</span><span>−${yen(t.discount)}</span></div>`:''}<div class="sum-row"><span>デモ送料</span><span>${t.shipping?yen(t.shipping):'無料'}</span></div><div class="sum-row total"><span>合計 <small>税込</small></span><strong>${yen(t.total)}</strong></div>${checkout?'<button id="place-order" class="btn full">デモ注文を確定する</button>':'<a href="#/checkout" class="btn full">購入手続きへ進む</a>'}<p class="note">実際の請求額は0円です。<br>購入・決済・発送は一切行われません。</p>${!checkout?`<form id="coupon-form" class="coupon"><label class="sr-only" for="coupon">クーポンコード</label><input id="coupon" placeholder="クーポンコード" value="${coupon}"><button>適用</button></form><p class="note">お試しコード：DEMO10（10%OFF）</p><p id="coupon-feedback" role="status" class="note">${coupon?'クーポン適用済み':''}</p>`:''}</aside>`;}
function cartPage(){if(!cart.length){main.innerHTML=`<div class="wrap"><div class="section-head"><h1>ショッピングカート</h1></div>${empty('カートは空です','気になる商品を見つけて、カートに追加してみましょう。')}</div>`;return;}main.innerHTML=`<div class="wrap"><div class="section-head"><h1>ショッピングカート</h1><p>${count()}点の商品</p></div><div class="columns"><div>${cartItems().map((p,i)=>`<article class="cart-row">${img(p)}<div><h3><a href="#/product/${p.id}">${p.name}</a></h3><p>カラー：${esc(p.color)} / 単価 ${yen(p.price)}</p><div class="qty"><button data-minus="${i}" aria-label="${p.name} ${p.color} の数量を減らす" ${p.quantity===1?'disabled':''}>−</button><output>${p.quantity}</output><button data-plus="${i}" aria-label="${p.name} ${p.color} の数量を増やす" ${p.quantity===9?'disabled':''}>＋</button></div><button class="delete" data-delete="${i}" aria-label="${p.name} ${p.color} を削除">削除</button></div><div class="line-price">${yen(p.price*p.quantity)}</div></article>`).join('')}<a class="text-link" href="#/">← お買い物を続ける</a></div>${summary()}</div></div>`;
for(const [attr,delta] of [['plus',1],['minus',-1],['delete',0]])document.querySelectorAll(`[data-${attr}]`).forEach(e=>e.onclick=()=>{const i=+e.dataset[attr];if(!delta)cart.splice(i,1);else cart[i].quantity=Math.min(9,Math.max(1,cart[i].quantity+delta));save();render(false);});
$('#coupon-form').onsubmit=e=>{e.preventDefault();const v=$('#coupon').value.trim().toUpperCase();if(v==='DEMO10'||!v){coupon=v;save();render(false);toast(v?'10%OFFを適用しました':'クーポンを解除しました');}else $('#coupon-feedback').textContent='このコードは利用できません。DEMO10 をお試しください。';};}
function checkout(){if(!cart.length){navigate('#/cart');return;}main.innerHTML=`<div class="wrap"><div class="breadcrumb"><a href="#/cart">カート</a> / ご注文の確認</div><div class="section-head"><h1>ご注文の確認</h1><p>ログイン・個人情報の入力は不要です</p></div><div class="demo-callout">デモ注文です。お届け先・お支払い情報は架空の固定データです。実際の購入は行われません。</div><div class="columns"><div><section class="checkout-section"><h2>1. お届け先</h2><div class="fake-field">デモユーザー 様<br>〒000-0000 デモ県デモ市サンプル町 1-2-3<br>DEMO BUILDING 101<br><small>架空のお届け先 / 編集・入力は不要です</small></div></section><section class="checkout-section"><h2>2. お支払い方法</h2><div class="fake-field">デモ決済（請求なし）<br><small>カード番号や決済アカウントは使用しません</small></div></section><section class="checkout-section"><h2>3. 配送方法</h2><label><input type="radio" name="shipping" checked> 通常配送（デモ）</label><p class="note">発送は行われません。送料は画面内のシミュレーションです。</p></section><section class="checkout-section"><h2>4. 商品の確認</h2>${cartItems().map(p=>`<article class="cart-row">${img(p)}<div><h3>${p.name}</h3><p>${esc(p.color)} / ${p.quantity}点</p></div><span class="line-price">${yen(p.price*p.quantity)}</span></article>`).join('')}</section></div>${summary(true)}</div></div>`;
$('#place-order').onclick=e=>{e.currentTarget.disabled=true;const items=cartItems().map(p=>({id:p.id,name:p.name,image:p.image,color:p.color,quantity:p.quantity,price:p.price}));const order={id:'DEMO-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase(),createdAt:Date.now(),items,...totals(items,coupon)};orders=pruneOrders([order,...orders]);cart=[];coupon='';save();updateCount();navigate('#/account');showSuccess(order);};}
function showSuccess(order){openModal(`<button class="close" aria-label="閉じる">×</button><div class="success-mark" aria-hidden="true">✓</div><p class="eyebrow">DEMO ORDER COMPLETE</p><h2 id="modal-title">デモ購入が完了しました</h2><p class="note">注文番号 ${order.id}</p><div class="modal-lines">${order.items.map(p=>`<p><span>${esc(p.name)}<br><span class="note">${esc(p.color)} / ${p.quantity}点</span></span><span>${yen(p.price*p.quantity)}</span></p>`).join('')}</div>${order.discount?`<div class="sum-row"><span>クーポン割引</span><span>−${yen(order.discount)}</span></div>`:''}<div class="sum-row"><span>デモ送料</span><span>${yen(order.shipping)}</span></div><div class="sum-row total"><span>デモ注文合計</span><strong>${yen(order.total)}</strong></div><p class="demo-callout">実際の購入・決済・発送は行われません。<br>実際の請求額は0円です。</p><p class="note">購入履歴はこのブラウザ内で10分間、最新5件まで確認できます。</p><button class="btn full" id="view-history">購入履歴を見る</button>`);$('#view-history').onclick=()=>{modal.close();navigate('#/account');};}
function account(){orders=pruneOrders(orders);save();main.innerHTML=`<div class="wrap"><p class="eyebrow">MY PAGE / DEMO USER</p><div class="section-head"><h1>購入履歴</h1><p>デモユーザー</p></div><p class="history-note">このブラウザで行ったデモ注文を、各注文から10分間・最新5件まで表示します。<br>別のブラウザや端末には共有されません。${storageOK?'':'現在ブラウザの保存機能を利用できないため、再読み込みで消去されます。'}</p>${orders.length?orders.map(o=>`<article class="order-card"><div class="order-header"><span>${new Date(o.createdAt).toLocaleString('ja-JP')}</span><span>${esc(o.id)}</span><span>デモ購入完了</span></div><div class="order-body">${o.items.map(p=>`<div class="cart-row">${img(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.color)} / ${p.quantity}点</p></div><span class="line-price">${yen(p.price*p.quantity)}</span></div>`).join('')}<div class="sum-row"><span>デモ送料 ${yen(o.shipping)}${o.discount?` / 割引 −${yen(o.discount)}`:''}</span><strong>合計 ${yen(o.total)}</strong></div><p class="note">実際の請求なし · <span data-expires="${o.createdAt+TTL}"></span>後に履歴から消えます</p></div></article>`).join(''):empty('まだ購入履歴はありません','デモ注文を完了すると、ここに商品と金額が表示されます。')}<div class="reset-panel"><a href="#/" class="btn secondary">お買い物を続ける</a></div></div>`;updateTimers();}
function updateTimers(){document.querySelectorAll('[data-expires]').forEach(e=>{const s=Math.max(0,Math.ceil((+e.dataset.expires-Date.now())/1000));e.textContent=`${Math.floor(s/60)}分${String(s%60).padStart(2,'0')}秒`;});}
const prompt='この通販デモサイトで、5,000円以下のキッチン用品を探してください。候補を比較し、ステンレスボトルを1点、サンド色でカートに入れて、デモ注文を確定してください。最後に購入履歴で商品名と合計金額を確認して報告してください。このサイトは実際の購入・決済・発送を行わないデモです。';
function guide(){main.innerHTML=`<div class="wrap guide"><p class="eyebrow">ABOUT THIS DEMO</p><h1>安心して、最後までお買い物を。</h1><p>NOMAは、人とAIエージェントが通販サイトのブラウザ操作を試すための架空ストアです。実際の商品販売・購入・決済・発送は一切行いません。</p><h2>できること</h2><p>商品検索、カテゴリ・価格・在庫での絞り込み、並び替え、商品詳細の確認、カラー・数量の選択、カートの編集、クーポン適用、デモ注文、購入履歴の確認。</p><h2>データの扱い</h2><p>ログイン不要。住所やカード番号などの個人情報は入力しません。カートとデモ購入履歴はブラウザ内だけに保存され、外部サーバーには送信しません。購入履歴は各注文から10分で表示・保存対象から外れ、最新5件まで保持します。閉じている間の期限切れデータは、次に開いたときに削除します。</p><h2>Museへの依頼例</h2><div class="prompt">${prompt}</div><p>このページのURLと一緒に、上の文章をMuseに渡してください。操作は通常のリンク・ボタン・フォームで行えます。画面上の全金額・評価・在庫・商品はデモデータです。</p><h2>料金と表示のルール</h2><p>すべて税込。デモ送料は500円、割引後の商品小計が5,000円以上なら無料です。クーポン DEMO10 で商品小計から10%割引（1円未満切り捨て）。数量は1種類・1色につき最大9点です。</p><a class="btn" href="#/">デモをはじめる</a></div>`;}
function openModal(content){$('#modal-content').innerHTML=content;modal.showModal();modal.querySelector('.close')?.addEventListener('click',()=>modal.close());}
$('#guide-button').onclick=()=>navigate('#/guide');$('#reset-button').onclick=()=>openModal('<button class="close" aria-label="閉じる">×</button><h2 id="modal-title">デモデータをリセット</h2><p>このブラウザのカート・購入履歴・クーポンを消去します。</p><button class="btn full" id="confirm-reset">デモデータを消去する</button><button class="btn secondary full" id="cancel-reset">キャンセル</button>');
modal.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){cart=[];orders=[];coupon='';save();modal.close();navigate('#/');updateCount();toast('デモデータをリセットしました');}if(e.target.id==='cancel-reset')modal.close();});
$('#search-form').onsubmit=e=>{e.preventDefault();navigate('#/?q='+encodeURIComponent($('#search').value.trim()));};
function render(scroll=true){const [path,query='']=(location.hash.slice(1)||'/').split('?');const params=new URLSearchParams(query);document.querySelectorAll('nav [data-category]').forEach(e=>e.classList.toggle('active',path==='/'&&(params.get('category')||'')===e.dataset.category));updateCount();if(path==='/')listing(params);else if(path.startsWith('/product/'))detail(path.split('/')[2]);else if(path==='/cart')cartPage();else if(path==='/checkout')checkout();else if(path==='/account')account();else if(path==='/guide')guide();else main.innerHTML=`<div class="wrap">${empty('ページが見つかりません','商品一覧に戻って操作を続けられます。')}</div>`;document.title=(path==='/cart'?'カート':path==='/account'?'購入履歴':path==='/checkout'?'ご注文の確認':'暮らしの、ちょうどいい。')+' | NOMA Demo';if(scroll){window.scrollTo(0,0);main.focus({preventScroll:true});}}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
window.addEventListener('hashchange',()=>render());window.addEventListener('storage',e=>{if(e.key===KEY){load();render(false);}});
setInterval(()=>{const fresh=pruneOrders(orders);if(fresh.length!==orders.length){orders=fresh;save();if(location.hash.startsWith('#/account'))account();}updateTimers();},1000);
window.addEventListener('pageshow',()=>{orders=pruneOrders(orders);save();});render();
